// Ericka call feed: ElevenLabs post-call payload -> plumbing_leads row.
//
// BEFORE ACTIVATING, replace the two placeholders below:
//   SUPABASE_URL  = https://phtmarvmovozydxipmat.supabase.co  (the CRM project)
//   SERVICE_KEY   = Supabase Dashboard -> Settings -> API Keys -> service_role (secret)
//                   This key BYPASSES RLS. It lives only here, server-side. Never in the browser.

const SUPABASE_URL = 'PASTE_PROJECT_URL_HERE';
const SERVICE_KEY = 'PASTE_SERVICE_ROLE_KEY_HERE';

// Webhook v2 nests the posted JSON under .body; ElevenLabs wraps call data in .data.
const body = items[0].json.body ?? items[0].json;
const d = body.data ?? body;

// Per-agent values. Set `sub_account_id` as a dynamic variable on each client's
// ElevenLabs agent (or in the agent's data-collection schema) so every call is
// attributed to the right business. Adjust these paths if your agent uses
// different names — this is the one spot that may need tweaking.
const dyn = d.conversation_initiation_client_data?.dynamic_variables ?? {};
const dc = d.analysis?.data_collection_results ?? {};

// Flatten the turn-by-turn transcript into readable text.
let transcript = null;
if (Array.isArray(d.transcript)) {
  transcript = d.transcript
    .map((t) => `${t.role === 'agent' ? 'Ericka' : 'Caller'}: ${t.message ?? ''}`)
    .join('\n');
} else if (typeof d.transcript === 'string') {
  transcript = d.transcript;
}

const row = {
  call_id: d.conversation_id ?? null,
  sub_account_id: dyn.sub_account_id ?? dc.sub_account_id ?? null,
  customer_name: dyn.customer_name ?? dc.customer_name ?? 'Unknown caller',
  customer_phone: dyn.caller_phone ?? d.metadata?.phone_call?.from ?? '',
  customer_address: dyn.customer_address ?? dc.customer_address ?? '',
  plumbing_issue: d.analysis?.call_summary ?? dyn.issue ?? '',
  emergency_level: String(dc.emergency_level ?? dyn.emergency_level ?? 'standard').toLowerCase(),
  pipeline_stage: 'new_lead',
  transcript,
  ghl_opportunity_id: null,
  created_at: d.metadata?.start_time_unix_secs
    ? new Date(d.metadata.start_time_unix_secs * 1000).toISOString()
    : new Date().toISOString(),
};

if (!row.call_id) throw new Error('Payload has no conversation_id — refusing to insert.');
if (!row.sub_account_id) throw new Error('No sub_account_id on this call — set it on the agent.');

// Upsert keyed on call_id (unique index from migration 0002): ElevenLabs
// retries collapse into the same row instead of duplicating the call.
const res = await this.helpers.httpRequest({
  method: 'POST',
  url: `${SUPABASE_URL}/rest/v1/plumbing_leads?on_conflict=call_id`,
  headers: {
    apikey: SERVICE_KEY,
    Authorization: `Bearer ${SERVICE_KEY}`,
    'Content-Type': 'application/json',
    Prefer: 'resolution=merge-duplicates,return=minimal',
  },
  body: row,
  json: true,
});

return [{ json: { inserted: row.call_id, sub_account_id: row.sub_account_id } }];
